package com.hmdp.ai.runtime.node;
import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.domain.run.*;import com.hmdp.ai.domain.security.*;import com.hmdp.ai.domain.workflow.*;import org.junit.jupiter.api.Test;import java.time.Instant;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ControlNodeExecutorsTest {private final ObjectMapper mapper=new ObjectMapper();@Test void branchSelectsFirstMatchingPriorityEdge(){Map<String,Object>v=new HashMap<>();v.put("intent","SHOP_COMPARE");WorkflowNodeDefinition n=node("branch",WorkflowNodeType.BRANCH,"{}");List<WorkflowEdgeDefinition>e=Arrays.asList(edge("branch","compare","{\"eq\":[{\"var\":\"intent\"},\"SHOP_COMPARE\"]}",10,"compare"),edge("branch","other",null,0,"default"));NodeExecutionResult r=new BranchNodeExecutor(new ConditionDslEvaluator(mapper)).execute(context(n,v,e));assertEquals(Collections.singletonList("compare"),r.getNextNodeIds());}@Test void parallelReturnsAllBranchesInOrder(){WorkflowNodeDefinition n=node("parallel",WorkflowNodeType.PARALLEL,"{}");List<WorkflowEdgeDefinition>e=Arrays.asList(edge("parallel","a",null,2,null),edge("parallel","b",null,1,null));assertEquals(Arrays.asList("a","b"),new ParallelNodeExecutor(mapper).execute(context(n,new HashMap<>(),e)).getNextNodeIds());}@Test void foreachCapturesBoundedCollection(){Map<String,Object>v=new HashMap<>();v.put("shopIds",Arrays.asList(1L,2L));WorkflowNodeDefinition n=node("each",WorkflowNodeType.FOREACH,"{\"collectionVariable\":\"shopIds\"}");NodeExecutionResult r=new ForEachNodeExecutor(mapper).execute(context(n,v,Collections.emptyList()));assertEquals(2,r.getOutput().size());}@Test void loopStopsAtConfiguredLimit(){Map<String,Object>v=new HashMap<>();v.put("loop.loop.iteration",2);WorkflowNodeDefinition n=node("loop",WorkflowNodeType.LOOP,"{\"maxIterations\":2,\"terminationCondition\":{\"eq\":[1,2]}}");List<WorkflowEdgeDefinition>e=Arrays.asList(edge("loop","body",null,1,"body"),edge("loop","exit",null,0,"exit"));NodeExecutionResult r=new LoopNodeExecutor(mapper,new ConditionDslEvaluator(mapper)).execute(context(n,v,e));assertEquals("LOOP_ITERATION_LIMIT_EXCEEDED",r.getErrorCode());}private NodeExecutionContext context(WorkflowNodeDefinition n,Map<String,Object>v,List<WorkflowEdgeDefinition>e){WorkflowDefinition w=new WorkflowDefinition("v","t","w","wf",1,"{}","{}","{}","{}","DRAFT",Collections.singletonList(n),e);ExecutionContext x=new ExecutionContext("t","w","u","s",null,"r","a",1,"zh-CN","UTC",Collections.emptyList(),Collections.emptyList(),new AuthorizationContext(EnumSet.of(AiPermission.AGENT_RUN)),ExecutionBudget.defaults(),Instant.now().plusSeconds(30),Collections.emptyMap(),"trace");return new NodeExecutionContext(x,null,w,n,v,e);}private WorkflowNodeDefinition node(String c,WorkflowNodeType t,String cfg){return new WorkflowNodeDefinition(c,c,t,c,cfg,"{}","{}",1000,1);}private WorkflowEdgeDefinition edge(String s,String t,String c,int p,String l){return new WorkflowEdgeDefinition(s+t,s,t,c,p,l);}}
